1	// Cold Email Engine — LEAD-DATABASE bulk import + continuous ingestion core.
2	//
3	// PURE ORCHESTRATION over an injected `LeadStore` so the exact same idempotent
4	// dedup/ingest logic runs from (a) the admin server action, (b) the operator CLI
5	// script scripts/import-leads.ts, and (c) the tests (with an in-memory store, no
6	// DB). The store is the ONLY thing that touches Prisma.
7	//
8	// IDEMPOTENCY + HYGIENE GUARANTEES:
9	//   - Dedup by NORMALIZED email (primary key of a lead). A repeat of an email
10	//     already seen earlier in the same file is skipped (skippedDup).
11	//   - An incoming email that matches an existing contact UPDATES it (fills blanks,
12	//     re-adds to the target list) — never inserts a duplicate. So a re-import of
13	//     the same file inserts 0.
14	//   - An incoming email that matches an existing DEAD or globally-SUPPRESSED
15	//     contact is NOT resurrected (skippedDead) — no update, no re-add to a list.
16	//   - A brand-new email that is already on the global suppression list is refused
17	//     (skippedDead) — we never add a suppressed address.
18	//   - Secondary signal: phone/website(domain) are recorded on the Business but the
19	//     dedup key is always the email (the only reliable per-person identifier).
20	
21	import { normalizeEmail, emailDomain, normalizeDomain } from "@/lib/coldemail/compliance";
22	import { isDeadStatus, type EmailStatusValue } from "@/lib/coldemail/leaddb";
23	
24	// ---------------------------------------------------------------------------
25	// Row model + header spec
26	// ---------------------------------------------------------------------------
27	
28	/**
29	 * Canonical field names an import row can carry. The CSV header row is mapped onto
30	 * these via IMPORT_HEADER_ALIASES; a JSON array uses these keys directly.
31	 */
32	export type LeadRow = {
33	  email?: string;
34	  fullName?: string;
35	  title?: string;
36	  // Business fields:
37	  name?: string; // business name
38	  category?: string;
39	  businessType?: string;
40	  website?: string;
41	  phone?: string;
42	  addressLine?: string;
43	  city?: string;
44	  region?: string;
45	  country?: string;
46	  companySize?: string;
47	  // Provenance: the specific URL/page this contact's email was found on. Not stored on
48	  // the Contact/Business row — threaded through to the per-contact ConsentRecord.note so
49	  // a batch's lawful-basis evidence is checkable one contact at a time (see recordConsent).
50	  sourceUrl?: string;
51	};
52	
53	/**
54	 * Header alias → canonical field. Superset of the legacy Businesses importer so old
55	 * files keep working. Keys are compared lower-cased + trimmed.
56	 */
57	export const IMPORT_HEADER_ALIASES: Record<string, keyof LeadRow> = {
58	  email: "email",
59	  "email address": "email",
60	  "e-mail": "email",
61	  contactemail: "email",
62	  fullname: "fullName",
63	  "full name": "fullName",
64	  contact: "fullName",
65	  contactname: "fullName",
66	  "contact name": "fullName",
67	  name2: "fullName",
68	  person: "fullName",
69	  title: "title",
70	  role: "title",
71	  jobtitle: "title",
72	  "job title": "title",
73	  name: "name",
74	  business: "name",
75	  company: "name",
76	  "company name": "name",
77	  organization: "name",
78	  category: "category",
79	  industry: "category",
80	  type: "businessType",
81	  businesstype: "businessType",
82	  website: "website",
83	  url: "website",
84	  domain: "website",
85	  phone: "phone",
86	  tel: "phone",
87	  telephone: "phone",
88	  address: "addressLine",
89	  addressline: "addressLine",
90	  street: "addressLine",
91	  city: "city",
92	  region: "region",
93	  state: "region",
94	  province: "region",
95	  country: "country",
96	  size: "companySize",
97	  companysize: "companySize",
98	  employees: "companySize",
99	  source: "sourceUrl",
100	  sourceurl: "sourceUrl",
101	  "source url": "sourceUrl",
102	  source_url: "sourceUrl",
103	  foundat: "sourceUrl",
104	  "found at": "sourceUrl",
105	};
106	
107	/** Human-facing spec for the import UI + docs (defined in a client-safe module). */
108	export { IMPORT_HEADERS_SPEC } from "./import-spec";
109	
110	// ---------------------------------------------------------------------------
111	// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
112	// ---------------------------------------------------------------------------
113	
114	export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
115	  const records: string[][] = [];
116	  let field = "";
117	  let row: string[] = [];
118	  let inQuotes = false;
119	  const src = (text ?? "").replace(/\r\n?/g, "\n");
120	
121	  for (let i = 0; i < src.length; i++) {
122	    const c = src[i];
123	    if (inQuotes) {
124	      if (c === '"') {
125	        if (src[i + 1] === '"') {
126	          field += '"';
127	          i++;
128	        } else {
129	          inQuotes = false;
130	        }
131	      } else {
132	        field += c;
133	      }
134	    } else if (c === '"') {
135	      inQuotes = true;
136	    } else if (c === ",") {
137	      row.push(field);
138	      field = "";
139	    } else if (c === "\n") {
140	      row.push(field);
141	      records.push(row);
142	      row = [];
143	      field = "";
144	    } else {
145	      field += c;
146	    }
147	  }
148	  if (field.length > 0 || row.length > 0) {
149	    row.push(field);
150	    records.push(row);
151	  }
152	
153	  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
154	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
155	  const headers = nonEmpty[0].map((h) => h.trim());
156	  return { headers, rows: nonEmpty.slice(1) };
157	}
158	
159	/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
160	export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
161	  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
162	  return rows.map((r) => {
163	    const lead: LeadRow = {};
164	    cols.forEach((field, i) => {
165	      if (field) lead[field] = (r[i] ?? "").trim();
166	    });
167	    return lead;
168	  });
169	}
170	
171	// ---------------------------------------------------------------------------
172	// Normalisation + validation of a single lead row
173	// ---------------------------------------------------------------------------
174	
175	// Stricter than a bare "anything@anything.anything" check: the old pattern let
176	// through scraper/URL-decoding artifacts (a literal "%20"/"%e2%80%8b" prefix, a
177	// leading dot) that real addresses never have. The local part must start with an
178	// alphanumeric; each domain label must start and end with an alphanumeric.
179	const EMAIL_RE =
180	  /^[a-zA-Z0-9][a-zA-Z0-9._+'-]*@[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?)+$/;
181	
182	export type NormalizedLead = {
183	  email: string;
184	  domain: string;
185	  fullName: string;
186	  title: string;
187	  business: {
188	    name: string;
189	    category: string;
190	    businessType: string;
191	    website: string;
192	    phone: string;
193	    addressLine: string;
194	    city: string;
195	    region: string;
196	    country: string;
197	    companySize: string;
198	  };
199	  sourceUrl: string;
200	};
201	
202	/**
203	 * Normalise + validate a row. Returns null when there is no usable email — the lead
204	 * database is keyed on emailable people, so an email-less row can't be a lead. The
205	 * business name falls back to the email domain so a name-less row still imports.
206	 */
207	export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
208	  const email = normalizeEmail(raw.email);
209	  if (!email || !EMAIL_RE.test(email)) return null;
210	  const domain = emailDomain(email);
211	  const website = (raw.website ?? "").trim();
212	  const name = (raw.name ?? "").trim() || domain;
213	  return {
214	    email,
215	    domain,
216	    fullName: (raw.fullName ?? "").trim().slice(0, 160),
217	    title: (raw.title ?? "").trim().slice(0, 120),
218	    business: {
219	      name: name.slice(0, 160),
220	      category: (raw.category ?? "").trim().slice(0, 120),
221	      businessType: (raw.businessType ?? "").trim().slice(0, 120),
222	      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
223	      phone: (raw.phone ?? "").trim().slice(0, 60),
224	      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
225	      city: (raw.city ?? "").trim().slice(0, 120),
226	      region: (raw.region ?? "").trim().slice(0, 120),
227	      country: (raw.country ?? "").trim().slice(0, 120),
228	      companySize: (raw.companySize ?? "").trim().slice(0, 60),
229	    },
230	    sourceUrl: (raw.sourceUrl ?? "").trim().slice(0, 300),
231	  };
232	}
233	
234	// ---------------------------------------------------------------------------
235	// The store the ingest orchestrator drives (Prisma in prod, a fake in tests)
236	// ---------------------------------------------------------------------------
237	
238	export type ExistingContact = {
239	  id: string;
240	  businessId: string;
241	  emailStatus: EmailStatusValue | string;
242	  fullName: string;
243	  title: string;
244	};
245	
246	export interface LeadStore {
247	  /** Find a contact by NORMALIZED email, or null. */
248	  findContact(email: string): Promise<ExistingContact | null>;
249	  /** Is this email (or its domain) on the global suppression list? */
250	  isSuppressed(email: string): Promise<boolean>;
251	  /** Create a Business, return its id. */
252	  createBusiness(data: NormalizedLead["business"], batchId: string | null): Promise<string>;
253	  /** Create a Contact (status UNVERIFIED), return its id. */
254	  createContact(
255	    input: { businessId: string; email: string; fullName: string; title: string },
256	    batchId: string | null,
257	  ): Promise<string>;
258	  /** Fill blank fields on an existing contact (never overwrite non-empty). */
259	  updateContact(
260	    id: string,
261	    input: { fullName?: string; title?: string },
262	    batchId: string | null,
263	  ): Promise<void>;
264	  /** Add a contact to a list, idempotently (no-op if already a member). */
265	  addToList(contactId: string, listId: string): Promise<void>;
266	  /**
267	   * Record a lawful-basis consent row for a newly-created contact. `note`, when given,
268	   * is the per-contact provenance (the specific URL the email was found on) — kept
269	   * separate from `source` (a batch-wide label like "script import") so the evidence is
270	   * checkable contact-by-contact.
271	   */
272	  recordConsent(contactId: string, source: string, note?: string): Promise<void>;
273	}
274	
275	// ---------------------------------------------------------------------------
276	// The ingest orchestrator
277	// ---------------------------------------------------------------------------
278	
279	export type ImportResult = {
280	  totalRows: number;
281	  inserted: number;
282	  updated: number;
283	  skippedDead: number;
284	  skippedDup: number;
285	  skippedInvalid: number;
286	  contactIds: string[];
287	};
288	
289	export type IngestOptions = {
290	  store: LeadStore;
291	  listId: string | null;
292	  batchId?: string | null;
293	  recordConsent?: boolean;
294	  consentSource?: string;
295	};
296	
297	/**
298	 * Ingest normalized-or-raw rows into the lead database, idempotently.
299	 *
300	 * For each row (see file header for the full guarantee set): validate → dedup
301	 * within the file → look up the existing contact → refuse dead/suppressed →
302	 * update-or-insert → add to the target list. Returns the batch tally.
303	 */
304	export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
305	  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
306	  const result: ImportResult = {
307	    totalRows: rows.length,
308	    inserted: 0,
309	    updated: 0,
310	    skippedDead: 0,
311	    skippedDup: 0,
312	    skippedInvalid: 0,
313	    contactIds: [],
314	  };
315	
316	  const seen = new Set<string>(); // in-file dedup by normalized email
317	
318	  for (const raw of rows) {
319	    const lead = normalizeLeadRow(raw);
320	    if (!lead) {
321	      result.skippedInvalid++;
322	      continue;
323	    }
324	    if (seen.has(lead.email)) {
325	      result.skippedDup++;
326	      continue;
327	    }
328	    seen.add(lead.email);
329	
330	    const existing = await store.findContact(lead.email);
331	
332	    if (existing) {
333	      // NEVER resurrect a dead/suppressed contact.
334	      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
335	        result.skippedDead++;
336	        continue;
337	      }
338	      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
339	      await store.updateContact(
340	        existing.id,
341	        {
342	          fullName: existing.fullName ? undefined : lead.fullName || undefined,
343	          title: existing.title ? undefined : lead.title || undefined,
344	        },
345	        batchId,
346	      );
347	      if (listId) await store.addToList(existing.id, listId);
348	      result.updated++;
349	      result.contactIds.push(existing.id);
350	      continue;
351	    }
352	
353	    // Brand-new email: refuse if it's already globally suppressed (opted-out before
354	    // the contact row existed) — we never add a suppressed address.
355	    if (await store.isSuppressed(lead.email)) {
356	      result.skippedDead++;
357	      continue;
358	    }
359	
360	    const businessId = await store.createBusiness(lead.business, batchId);
361	    const contactId = await store.createContact(
362	      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
363	      batchId,
364	    );
365	    if (listId) await store.addToList(contactId, listId);
366	    if (recordConsent) await store.recordConsent(contactId, consentSource, lead.sourceUrl || undefined);
367	    result.inserted++;
368	    result.contactIds.push(contactId);
369	  }
370	
371	  return result;
372	}
