1	// Cold Email Engine — Prisma-backed LeadStore for the bulk importer.
2	//
3	// The ONE adapter that maps lib/coldemail/import.ts's store-agnostic ingest logic
4	// onto Prisma. Shared by the admin server action (lib/actions-coldemail.ts) and the
5	// operator CLI (scripts/import-leads.ts) so both go through identical, tested,
6	// idempotent dedup logic. Plain module (no "use server") — safe to import from a
7	// tsx script or the worker.
8	
9	import { db } from "@/lib/db";
10	import { normalizeEmail, emailDomain } from "@/lib/coldemail/compliance";
11	import type { LeadStore, NormalizedLead, ExistingContact } from "@/lib/coldemail/import";
12	
13	/** Build a LeadStore over the live Prisma client, stamping `source` on new Businesses. */
14	export function prismaLeadStore(businessSource = "import"): LeadStore {
15	  return {
16	    async findContact(email: string): Promise<ExistingContact | null> {
17	      const c = await db.contact.findUnique({
18	        where: { email: normalizeEmail(email) },
19	        select: { id: true, businessId: true, emailStatus: true, fullName: true, title: true },
20	      });
21	      return c ? { ...c, emailStatus: c.emailStatus as string } : null;
22	    },
23	
24	    async isSuppressed(email: string): Promise<boolean> {
25	      const e = normalizeEmail(email);
26	      const domain = emailDomain(e);
27	      const hit = await db.suppression.findFirst({
28	        where: {
29	          scope: "GLOBAL",
30	          OR: [{ email: e }, ...(domain ? [{ domain }] : [])],
31	        },
32	        select: { id: true },
33	      });
34	      return !!hit;
35	    },
36	
37	    async createBusiness(data: NormalizedLead["business"], _batchId: string | null): Promise<string> {
38	      const b = await db.business.create({ data: { ...data, source: businessSource } });
39	      return b.id;
40	    },
41	
42	    async createContact(input, batchId): Promise<string> {
43	      const c = await db.contact.create({
44	        data: {
45	          businessId: input.businessId,
46	          email: normalizeEmail(input.email),
47	          fullName: input.fullName,
48	          title: input.title,
49	          emailStatus: "UNVERIFIED",
50	          ...(batchId ? { importBatchId: batchId } : {}),
51	        },
52	        select: { id: true },
53	      });
54	      return c.id;
55	    },
56	
57	    async updateContact(id, input, batchId): Promise<void> {
58	      const data: Record<string, unknown> = {};
59	      if (input.fullName) data.fullName = input.fullName;
60	      if (input.title) data.title = input.title;
61	      if (batchId) data.importBatchId = batchId;
62	      if (Object.keys(data).length === 0) return;
63	      await db.contact.update({ where: { id }, data });
64	    },
65	
66	    async addToList(contactId, listId): Promise<void> {
67	      // Idempotent — the unique (listId, contactId) makes a repeat a no-op.
68	      await db.emailListMember.createMany({ data: [{ contactId, listId }], skipDuplicates: true });
69	    },
70	
71	    async recordConsent(contactId, source, note): Promise<void> {
72	      await db.consentRecord.create({
73	        data: {
74	          contactId,
75	          basis: "LEGITIMATE_INTEREST",
76	          source: source.slice(0, 120),
77	          ...(note ? { note: note.slice(0, 300) } : {}),
78	        },
79	      });
80	    },
81	  };
82	}
