257	function makeFakeStore(seed?: {
258	  contacts?: { email: string; emailStatus: EmailStatusValue; fullName?: string; title?: string }[];
259	  suppressed?: string[];
260	}) {
261	  let bizSeq = 0;
262	  let conSeq = 0;
263	  const contacts = new Map<string, ExistingContact>();
264	  const suppressed = new Set(seed?.suppressed ?? []);
265	  const listMembers = new Set<string>();
266	  const createdContacts: string[] = [];
267	  for (const c of seed?.contacts ?? []) {
268	    const id = `seed-${conSeq++}`;
269	    contacts.set(c.email, {
270	      id,
271	      businessId: `seedbiz-${id}`,
272	      emailStatus: c.emailStatus,
273	      fullName: c.fullName ?? "",
274	      title: c.title ?? "",
275	    });
276	  }
277	  const store: LeadStore = {
278	    async findContact(email) {
279	      return contacts.get(email) ?? null;
280	    },
281	    async isSuppressed(email) {
282	      return suppressed.has(email);
283	    },
284	    async createBusiness(_data: NormalizedLead["business"]) {
285	      return `biz-${bizSeq++}`;
286	    },
287	    async createContact(input) {
288	      const id = `con-${conSeq++}`;
289	      contacts.set(input.email, {
290	        id,
291	        businessId: input.businessId,
292	        emailStatus: "UNVERIFIED",
293	        fullName: input.fullName,
294	        title: input.title,
295	      });
296	      createdContacts.push(id);
297	      return id;
298	    },
299	    async updateContact(id, input) {
300	      for (const [email, c] of contacts) {
301	        if (c.id === id) {
302	          contacts.set(email, {
303	            ...c,
304	            fullName: input.fullName ?? c.fullName,
305	            title: input.title ?? c.title,
306	          });
307	        }
308	      }
309	    },
310	    async addToList(contactId, listId) {
311	      listMembers.add(`${listId}:${contactId}`);
312	    },
313	    async recordConsent() {
314	      /* no-op */
315	    },
316	  };
317	  return { store, contacts, listMembers, createdContacts };
318	}
