311	// LEAD-DB bulk importer — idempotent ingest into a chosen list + ImportBatch record
312	// ---------------------------------------------------------------------------
313	
314	/** Cap rows a single web request ingests; larger files should use scripts/import-leads.ts. */
315	const IMPORT_MAX_ROWS = 5000;
316	
317	/**
318	 * Bulk-import leads (CSV upload or pasted CSV) into the lead database and assign
319	 * them to a chosen EmailList. Idempotent: dedup by normalized email, update
320	 * existing / insert new / never duplicate, and NEVER resurrect a dead/suppressed
321	 * contact. Records an ImportBatch with the tally.
322	 */
323	export async function importLeads(_prev: ActionState, formData: FormData): Promise<ActionState> {
324	  await requireArea("platform");
325	
326	  // Accept either an uploaded file or pasted text.
327	  let csv = String(formData.get("csv") ?? "");
328	  const file = formData.get("file");
329	  if ((!csv || !csv.trim()) && file && typeof file === "object" && "text" in file) {
330	    try {
331	      csv = await (file as File).text();
332	    } catch {
333	      /* ignore */
334	    }
335	  }
336	  if (!csv.trim()) return { error: "Upload a CSV file or paste some rows first." };
337	
338	  const listId = String(formData.get("listId") ?? "").trim() || null;
339	  const recordConsentAll = formData.get("recordConsent") === "on" || formData.get("recordConsent") === "true";
340	  const batchName = String(formData.get("batchName") ?? "").trim() || `Import ${new Date().toISOString().slice(0, 16)}`;
341	  const source = String(formData.get("source") ?? "paste") === "csv-upload" ? "csv-upload" : "paste";
342	
343	  const { headers, rows } = parseImportCsv(csv);
344	  if (headers.length === 0 || rows.length === 0) {
345	    return { error: "Could not find a header row and at least one data row." };
346	  }
347	  if (!headers.map((h) => h.trim().toLowerCase()).some((h) => h === "email" || h.includes("mail"))) {
348	    return { error: "CSV needs at least an 'email' column." };
349	  }
350	  if (rows.length > IMPORT_MAX_ROWS) {
351	    return {
352	      error: `That file has ${rows.length} rows — over the ${IMPORT_MAX_ROWS}-row web limit. Use scripts/import-leads.ts for large files.`,
353	    };
354	  }
355	
356	  if (listId) {
357	    const list = await db.emailList.findUnique({ where: { id: listId }, select: { id: true } });
358	    if (!list) return { error: "Pick a valid list." };
359	  }
360	
361	  const leadRows: LeadRow[] = csvToLeadRows(headers, rows);
362	
363	  // Create the batch first so new/updated contacts can reference it, then finalise counts.
364	  const batch = await db.importBatch.create({
365	    data: { name: batchName.slice(0, 160), source, listId },
366	    select: { id: true },
367	  });
368	
369	  let result;
370	  try {
371	    result = await ingestLeads(leadRows, {
372	      store: prismaLeadStore("import"),
373	      listId,
374	      batchId: batch.id,
375	      recordConsent: recordConsentAll,
376	      consentSource: "bulk import",
377	    });
378	  } catch (err) {
379	    await logEvent("error", "coldemail.import.leads", { message: String(err), batchId: batch.id });
380	    return { error: "Import failed partway through. Some rows may have been imported; check the batch record." };
381	  }
382	
383	  await db.importBatch.update({
384	    where: { id: batch.id },
385	    data: {
386	      totalRows: result.totalRows,
387	      inserted: result.inserted,
388	      updated: result.updated,
389	      skippedDead: result.skippedDead,
390	      skippedDup: result.skippedDup,
391	      skippedInvalid: result.skippedInvalid,
392	    },
393	  });
394	
395	  revalidatePath("/admin/coldemail/import");
396	  revalidatePath("/admin/coldemail/businesses");
397	  revalidatePath("/admin/coldemail/lists");
398	  revalidatePath("/admin/coldemail");
399	  return {
400	    ok: true,
401	    error: `Imported: ${result.inserted} new, ${result.updated} updated, ${result.skippedDead} dead/suppressed skipped, ${result.skippedDup} in-file dupes, ${result.skippedInvalid} invalid.`,
402	  };
403	}
