709	/**
710	 * Launch a campaign: set status SENDING + stamp launchedAt. REFUSES if the brand
711	 * is not send-eligible (compliance, reputation isolation, or circuit-breaker
712	 * pause) — the same gate the worker enforces, surfaced with reasons.
713	 */
714	export async function launchCampaign(campaignId: string): Promise<ActionState> {
715	  await requireArea("platform");
716	  const campaign = await db.coldCampaign.findUnique({
717	    where: { id: campaignId },
718	    include: { brand: true, _count: { select: { steps: true } } },
719	  });
720	  if (!campaign) return { error: "Campaign not found." };
721	  if (campaign._count.steps === 0) return { error: "Add at least one sequence step before launching." };
722	
723	  const eligibility = await brandEligibility(campaign.brand);
724	  if (!eligibility.eligible) {
725	    return { error: `Cannot launch — the brand is not eligible to send: ${eligibility.reasons.join("; ")}` };
726	  }
727	
728	  await db.coldCampaign.update({
729	    where: { id: campaignId },
730	    // Preserve an earlier launchedAt on resume so scheduling stays stable.
731	    data: { status: "SENDING", launchedAt: campaign.launchedAt ?? new Date() },
