1048	// ---------------------------------------------------------------------------
1049	// LIVE DNS verification (SPF / DKIM / DMARC + tracking CNAME)
1050	//
1051	// Real DNS lookups, NOT self-attested checkboxes. The records are read through
1052	// the zone's AUTHORITATIVE nameservers (lib/mail/deliverability.ts) rather than
1053	// the local resolver — this host's /etc/hosts once produced a confidently wrong
1054	// diagnosis, so cold-email verification must never trust the system resolver.
1055	// The pure recognition lives in lib/coldemail/dns.ts and is unit-tested.
1056	// ---------------------------------------------------------------------------
1057	
1058	/**
1059	 * Run live SPF / DKIM / DMARC (and optional tracking-CNAME) lookups for `domain`.
1060	 * Read-only: returns each record verified/not with the raw value found (or the
1061	 * reason it failed). Does NOT write any flags — callers that persist are
1062	 * `verifyBrandDns` / `verifySendingDomainDns`.
1063	 */
1064	export async function verifyDomainDns(
1065	  domain: string,
1066	  dkimSelector?: string,
1067	  trackingDomain?: string,
1068	): Promise<DnsVerifyResult> {
1069	  await requireArea("platform");
1070	  const host = normalizeDomain(domain);
1071	  const selector = normalizeSelector(dkimSelector);
1072	  const checkedAt = new Date().toISOString();
1073	  const track = normalizeDomain(trackingDomain);
1074	
1075	  if (!host) {
1076	    const err = "No domain to check.";
1077	    const fail = { verified: false, record: null, error: err };
1078	    return { domain: host, dkimSelector: selector, spf: fail, dkim: fail, dmarc: fail, tracking: null, checkedAt, lookupError: err };
1079	  }
1080	
1081	  const auth = await authoritativeResolver(host);
1082	  if ("error" in auth) {
1083	    const fail = { verified: false, record: null, error: auth.error };
1084	    return {
1085	      domain: host,
1086	      dkimSelector: selector,
1087	      spf: fail,
1088	      dkim: fail,
1089	      dmarc: fail,
1090	      tracking: track ? { host: track, verified: false, record: null, error: auth.error } : null,
1091	      checkedAt,
1092	      lookupError: auth.error,
1093	    };
1094	  }
1095	
1096	  const { resolver } = auth;
1097	  const [apexTxt, dkimTxt, dmarcTxt, cname] = await Promise.all([
1098	    txtAt(resolver, host),
1099	    txtAt(resolver, `${selector}._domainkey.${host}`),
1100	    txtAt(resolver, `_dmarc.${host}`),
1101	    track ? cnameAt(resolver, track) : Promise.resolve(null),
1102	  ]);
1103	
1104	  return {
1105	    domain: host,
1106	    dkimSelector: selector,
1107	    spf: buildSpfCheck(apexTxt),
1108	    dkim: buildDkimCheck(dkimTxt, selector),
1109	    dmarc: buildDmarcCheck(dmarcTxt),
1110	    tracking: track ? { host: track, ...buildCnameCheck(cname) } : null,
1111	    checkedAt,
1112	    lookupError: null,
1113	  };
1114	}
