226	  // Cumulative offset (days) at each step.
227	  let cumulative = 0;
228	  const stepSchedule = steps.map((s) => {
229	    cumulative += Math.max(0, s.delayDays);
230	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
231	  });
