240	  // / complained / unsubscribed) or globally/brand-suppressed contact. The send-time
241	  // suppression re-check remains as defence-in-depth for rows queued earlier.
242	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
243	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
244	    select: { email: true, domain: true, scope: true, brandId: true },
245	  });
